import { describe, expect, it } from 'vitest'
import { motionFromApi, Path, poseAt, type Vertex } from '../motion'

// Shared fixture generated by the Python model (backend/tests/motion_cases.py): both twins must agree.
import fixture from '../../../../backend/tests/fixtures/motion_cases.json'
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const fx = fixture as any

describe('motion twin', () => {
  for (const name of Object.keys(fx.cases)) {
    it(`reproduces the Python model: ${name}`, () => {
      const sp = fx.specs[name]
      const m = motionFromApi({ kind: 'path', path: fx.path as Vertex[], speeds: fx.speeds, startS: sp.start_s ?? 0, offsetS: sp.offset_s ?? 0, holdS: sp.hold_s ?? 0,
        mode: sp.mode, airborne: !!sp.airborne, fuelStart: sp.fuel_start ?? null, fuelBurnPerKm: sp.fuel_burn_per_km ?? 0, trim: sp.trim ?? [0, 0] }, new Map<string, Path>())
      fx.times.forEach((t: number, i: number) => {
        const [lng, lat, alt, heading, pitch, bank, speed, phase, fuel] = fx.cases[name][i]
        const p = poseAt(m, t)
        expect(p.lng).toBeCloseTo(lng, 9); expect(p.lat).toBeCloseTo(lat, 9)
        if (alt === null) expect(p.alt).toBeNull(); else expect(p.alt!).toBeCloseTo(alt, 6)
        expect(p.heading).toBeCloseTo(heading, 5); expect(p.pitch).toBeCloseTo(pitch, 5); expect(p.bank).toBeCloseTo(bank, 5)
        expect(p.speed).toBeCloseTo(speed, 9); expect(p.phase).toBe(phase)
        if (fuel === null) expect(p.fuel).toBeNull(); else expect(p.fuel!).toBeCloseTo(fuel, 6)
      })
    })
  }
})
